// CdpClient 实现：方法调用、evaluate 封装、事件聚合与超时清理
#include "server/cdp_client.h" // 自身声明
#include <windows.h> // GetTickCount64
#include "include/cef_parser.h" // CefParseJSON
#include "include/wrapper/cef_helpers.h" // CEF_REQUIRE_UI_THREAD
#include "utils/json_util.h" // JSON 工具
namespace { const size_t kConsoleCap = 200; const size_t kNetworkCap = 300; const unsigned long long kCallTimeoutMs = 60000; } // 缓冲上限与调用超时
std::string ConsoleLevelName(cef_log_severity_t level) { switch (level) { case LOGSEVERITY_ERROR: case LOGSEVERITY_FATAL: return "error"; case LOGSEVERITY_WARNING: return "warning"; case LOGSEVERITY_INFO: return "info"; default: return "debug"; } } // 日志级别名归一
CdpClient::CdpClient(CefRefPtr<CefBrowser> browser) : browser_(browser) {} // 绑定浏览器
void CdpClient::Attach() { CEF_REQUIRE_UI_THREAD(); if (browser_ == nullptr || registration_ != nullptr) return; registration_ = browser_->GetHost()->AddDevToolsMessageObserver(this); } // 注册观察者（幂等）
void CdpClient::AddConsole(const ConsoleEntry& entry) { CEF_REQUIRE_UI_THREAD(); console_.push_back(entry); if (console_.size() > kConsoleCap) console_.erase(console_.begin(), console_.begin() + static_cast<long>(console_.size() - kConsoleCap)); } // 控制台环形缓冲追加
void CdpClient::PurgeStale() { const unsigned long long now = ::GetTickCount64(); for (auto it = pending_tick_.begin(); it != pending_tick_.end();) { if (now - it->second > kCallTimeoutMs) { auto cb = pending_.find(it->first); if (cb != pending_.end()) { CdpCallback callback = cb->second; pending_.erase(cb); callback(false, nullptr, "CDP 调用超时"); } it = pending_tick_.erase(it); } else ++it; } } // 清理超过 60s 未返回的挂起调用并回调超时错误
void CdpClient::Call(const std::string& method, CefRefPtr<CefDictionaryValue> params, CdpCallback cb) { CEF_REQUIRE_UI_THREAD(); PurgeStale(); if (browser_ == nullptr || registration_ == nullptr) { if (cb) cb(false, nullptr, "浏览器未就绪"); return; } const int id = next_id_++; if (cb) { pending_[id] = cb; pending_tick_[id] = ::GetTickCount64(); } const int assigned = browser_->GetHost()->ExecuteDevToolsMethod(id, method, params); if (assigned == 0) { pending_.erase(id); pending_tick_.erase(id); if (cb) cb(false, nullptr, "CDP 方法提交失败: " + method); } } // 发 CDP 方法调用：登记回调，提交失败立即报错
CefRefPtr<CefDictionaryValue> CdpClient::EvalParams(const std::string& expression, bool await_promise) { CefRefPtr<CefDictionaryValue> params = MakeDict(); params->SetString("expression", expression); params->SetBool("returnByValue", true); params->SetBool("awaitPromise", await_promise); params->SetBool("userGesture", true); return params; } // 构造 Runtime.evaluate 参数
void CdpClient::Evaluate(const std::string& expression, bool await_promise, EvalCallback cb) { Call("Runtime.evaluate", EvalParams(expression, await_promise), [cb](bool ok, CefRefPtr<CefDictionaryValue> result, const std::string& error) { if (cb == nullptr) return; if (!ok) { cb(false, nullptr, error); return; } CefRefPtr<CefDictionaryValue> inner = result->GetDictionary("result"); CefRefPtr<CefDictionaryValue> details = result->GetDictionary("exceptionDetails"); if (details != nullptr) { std::string text = StrOf(details, "text"); CefRefPtr<CefDictionaryValue> exception = details->GetDictionary("exception"); if (exception != nullptr) { const std::string desc = StrOf(exception, "description"); if (!desc.empty()) text = desc; } cb(false, nullptr, text.empty() ? "JS 执行异常" : text); return; } if (inner == nullptr) { cb(true, nullptr, ""); return; } cb(true, inner->GetValue("value"), ""); }); } // evaluate 封装：exceptionDetails 优先取 exception.description
void CdpClient::Screenshot(const std::string& format, bool full_page, CefRefPtr<CefDictionaryValue> clip, CdpCallback cb) { CefRefPtr<CefDictionaryValue> params = MakeDict(); params->SetString("format", format == "jpeg" ? "jpeg" : "png"); if (clip != nullptr) { params->SetDictionary("clip", clip); params->SetBool("captureBeyondViewport", false); } else params->SetBool("captureBeyondViewport", full_page); Call("Page.captureScreenshot", params, cb); } // 截图：带 clip 时只截可见区域
void CdpClient::DispatchMouse(CefRefPtr<CefDictionaryValue> params, CdpCallback cb) { Call("Input.dispatchMouseEvent", params, cb); } // 鼠标事件
void CdpClient::DispatchKey(CefRefPtr<CefDictionaryValue> params, CdpCallback cb) { Call("Input.dispatchKeyEvent", params, cb); } // 键盘事件
void CdpClient::InsertText(const std::string& text, CdpCallback cb) { CefRefPtr<CefDictionaryValue> params = MakeDict(); params->SetString("text", text); Call("Input.insertText", params, cb); } // 插入文本（输入法式提交）
void CdpClient::EnableNetwork() { CEF_REQUIRE_UI_THREAD(); if (network_enabled_) return; network_enabled_ = true; Call("Network.enable", MakeDict(), nullptr); } // 只开一次 Network domain
bool CdpClient::OnDevToolsMessage(CefRefPtr<CefBrowser> browser, const void* message, size_t message_size) { CEF_REQUIRE_UI_THREAD(); CefRefPtr<CefValue> parsed = CefParseJSON(message, message_size, JSON_PARSER_RFC); if (parsed == nullptr || parsed->GetType() != VTYPE_DICTIONARY) return true; CefRefPtr<CefDictionaryValue> frame = parsed->GetDictionary(); if (frame->HasKey("method")) { HandleEvent(StrOf(frame, "method"), frame->GetDictionary("params")); return true; } if (!frame->HasKey("id")) return true; const int id = IntOf(frame, "id"); auto it = pending_.find(id); if (it == pending_.end()) return true; CdpCallback callback = it->second; pending_.erase(it); pending_tick_.erase(id); CefRefPtr<CefDictionaryValue> error = frame->GetDictionary("error"); if (error != nullptr) callback(false, nullptr, StrOf(error, "message")); else { CefRefPtr<CefDictionaryValue> result = frame->GetDictionary("result"); callback(true, result != nullptr ? result : MakeDict(), ""); } return true; } // CDP 消息回调：method 帧走事件聚合，id 帧匹配挂起调用并回包
void CdpClient::HandleEvent(const std::string& method, CefRefPtr<CefDictionaryValue> params) { if (params == nullptr || !network_enabled_) return; const std::string request_id = StrOf(params, "requestId"); if (request_id.empty()) return; if (method == "Network.requestWillBeSent") { NetworkEntry entry; entry.request_id = request_id; CefRefPtr<CefDictionaryValue> request = params->GetDictionary("request"); if (request != nullptr) { entry.url = StrOf(request, "url"); entry.method = StrOf(request, "method"); } ArgGetDouble(params, "timestamp", entry.start_ts); network_index_[request_id] = network_.size(); network_.push_back(entry); } else { auto idx = network_index_.find(request_id); if (idx == network_index_.end()) return; NetworkEntry& entry = network_[idx->second]; if (method == "Network.responseReceived") { CefRefPtr<CefDictionaryValue> response = params->GetDictionary("response"); if (response != nullptr) entry.status = IntOf(response, "status"); entry.type = StrOf(params, "type"); ArgGetDouble(params, "timestamp", entry.end_ts); } else if (method == "Network.loadingFailed") { entry.error = StrOf(params, "errorText"); ArgGetDouble(params, "timestamp", entry.end_ts); } else if (method == "Network.loadingFinished") { ArgGetDouble(params, "timestamp", entry.end_ts); } } if (network_.size() > kNetworkCap) { const size_t drop = network_.size() - kNetworkCap + 50; network_.erase(network_.begin(), network_.begin() + static_cast<long>(drop)); network_index_.clear(); for (size_t i = 0; i < network_.size(); ++i) network_index_[network_[i].request_id] = i; } } // Network 事件聚合：请求/响应/失败/完成写环形缓冲，超限整批丢弃并重建索引
